export const NIGERIA_CITIES = Object.freeze(Object.fromEntries(
  Object.entries(cities).map(([state, names]) => [state, Object.freeze(names)])
));

export function isNigeriaCity(state, city) {
  return typeof state === "string" && typeof city === "string" &&
    Object.hasOwn(NIGERIA_CITIES, state) && NIGERIA_CITIES[state].includes(city);
}

export function nigeriaCityLabel(state, city) {
  if (!isNigeriaCity(state, city)) return null;
  const label = `${city}, ${state}`;
  return label.length <= 100 ? label : null;
}

// A legacy city-only value is safe only when its name occurs in one state.
// Case-insensitive indexing also rejects names shared with a casing variation.
const legacyCities = new Map();
for (const [state, names] of Object.entries(NIGERIA_CITIES)) {
  for (const city of names) {
    const key = city.toLowerCase();
    if (legacyCities.has(key)) legacyCities.set(key, null);
    else legacyCities.set(key, { state, city });
  }
}

export function parseNigeriaCityLabel(value) {
  if (typeof value !== "string" || value.length > 100) return null;
  const label = value.trim();
  if (!label) return null;
  for (const state of Object.keys(NIGERIA_CITIES)) {
    const suffix = `, ${state}`;
    if (label.endsWith(suffix)) {
      const city = label.slice(0, -suffix.length);
      return nigeriaCityLabel(state, city) === label ? { state, city } : null;
    }
  }
  const match = legacyCities.get(label.toLowerCase());
  return match && match.city === label && nigeriaCityLabel(match.state, match.city)
    ? { state: match.state, city: match.city } : null;
}
